/**
 * Учебный контент.
 *
 * Разделы «Области AI» устроены плоско: раздел = одна страница.
 * У такого раздела есть `page` — идентификатор темы, которая и открывается
 * по тапу; промежуточного списка нет, учить проще.
 * У раздела со списком вместо `page` стоит `topics`, а у большого раздела —
 * `modules` (`#/m/<раздел>/<модуль>`). Модуль тоже бывает одной страницей —
 * тогда у него свой `page`.
 *
 * `group` решает, под каким заголовком раздел стоит на главной:
 * 'ai' — области AI в порядке изучения, 'claude' — всё про Claude,
 * 'sdd' — разработка от спецификации.
 * `cards: true` включает в разделе колоду для интервального повторения.
 *
 * Большинство страниц пока заглушки: есть `outline` — план того, что на
 * странице будет, — и нет ни одного заполненного блока. Страница так и
 * говорит, а панель практики с AI на ней не показывается: спрашивать не по чему.
 *
 * Поля темы:
 *   title    — заголовок, intro — одна строка «о чём это»
 *   outline  — ['пункт плана', …]   что появится на странице
 *   diagram  — { caption, svg }     схема под вступлением; svg свой, не от модели
 *   source   — откуда конспект (курс, PDF, статья)
 *   domain   — домен экзамена CCAR-F ('D1'…'D5')
 *   points   — [{ t, d }]           ключевая мысль и расшифровка
 *   terms    — [{ en, ru, note }]   термин → перевод → когда употребляется
 *   commands — [{ cmd, what }]      команда и что делает (копируется по клику)
 *   qa       — [{ q, a }]           вопрос на самопроверку (в контекст для AI)
 *   check    — [{ q, a }]           проверочные вопросы по-английски, видны на странице
 *   code     — [{ title, body }]
 *   links    — [{ title, href }]
 *
 * terms и qa автоматически становятся карточками для повторения — см. js/cards.js.
 */

