            body: `---
name: release-notes
description: Собирает release notes из merged PR
  за период. Используй, когда просят changelog,
  релизные заметки или список изменений.
allowed-tools: Bash(git log:*), Bash(gh pr:*),
  Read, Write
---

## Что делать

1. Собрать merged PR за период:
   gh pr list --state merged --json title,labels
2. Сгруппировать по меткам: feat, fix, chore
3. Записать в CHANGELOG.md по template.md

## Правила

- Заголовки берём из PR, не из коммитов
- Внутренние правки (chore, ci) не включаем
- Ломающие изменения — разделом сверху`,
